"""Slot archival uses generated bytes in temporary fake emulator folders."""
from pathlib import Path
import hashlib
import json
import sys
import tempfile
import unittest
from unittest.mock import patch

sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from editor import slot_archive as slots,state_store as store
import test_state_store as fixtures


class SlotArchiveTests(unittest.TestCase):
    def fixture(self):
        temporary=tempfile.TemporaryDirectory()
        self.addCleanup(temporary.cleanup)
        root=Path(temporary.name)/'emulator'
        config=fixtures.portable(root)
        states=(root/'sstates').resolve()
        states.mkdir()
        return root,states,config

    def write(self,states,slot,data=b'preserve this save',*,nested=False):
        path=store._candidates(states,slot)[int(nested)]
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_bytes(data)
        return path

    def test_list_distinguishes_empty_single_and_ambiguous_slots_without_writes(self):
        root,states,config=self.fixture()
        flat=self.write(states,2,b'abc')
        nested=self.write(states,2,b'12345',nested=True)
        before=config.read_bytes()
        rows=slots.list_slots(root)
        self.assertEqual(len(rows),10)
        self.assertEqual(rows[2]['paths'],[str(flat),str(nested)])
        self.assertEqual(rows[2]['total_bytes'],8)
        self.assertTrue(rows[2]['occupied'])
        self.assertFalse(rows[2]['blocked'])
        self.assertFalse(rows[9]['occupied'])
        self.assertEqual(config.read_bytes(),before)
        self.assertFalse((root/'editor-slot-backups').exists())

    def test_archive_both_layouts_preserves_bytes_other_slots_and_config(self):
        root,states,config=self.fixture()
        paths=[self.write(states,8,b'flat'),self.write(states,8,b'nested',nested=True)]
        other=self.write(states,7,b'unrelated')
        before=config.read_bytes()
        result=slots.archive_slot(root,8)
        self.assertEqual(result['slot'],8)
        self.assertFalse(any(path.exists() for path in paths))
        self.assertEqual([Path(p).read_bytes() for p in result['paths']],[b'flat',b'nested'])
        self.assertEqual(other.read_bytes(),b'unrelated')
        self.assertEqual(config.read_bytes(),before)
        for item in result['backups']:
            self.assertEqual(hashlib.sha256(Path(item['path']).read_bytes()).hexdigest(),item['sha256'])
        manifest=json.loads((Path(result['archive_directory'])/'backup.json').read_text(encoding='utf8'))
        self.assertEqual(manifest['files'],result['backups'])
        self.assertFalse(slots.list_slots(root)[8]['occupied'])

    def test_empty_or_invalid_save_is_archived_without_destroying_its_bytes(self):
        for data in (b'',b'not a valid ZIP'):
            with self.subTest(data=data):
                root,states,_config=self.fixture()
                source=self.write(states,3,data)
                result=slots.archive_slot(root,3)
                self.assertEqual(Path(result['paths'][0]).read_bytes(),data)
                self.assertFalse(source.exists())

    def test_invalid_or_empty_slot_is_rejected_before_creating_backup(self):
        root,states,_config=self.fixture()
        for slot in (True,-1,10,2.0,'2'):
            with self.subTest(slot=slot),self.assertRaises(slots.SlotArchiveError):
                slots.archive_slot(root,slot)
        with self.assertRaisesRegex(slots.SlotArchiveError,'já está livre'):
            slots.archive_slot(root,2)
        self.assertFalse((root/'editor-slot-backups').exists())

    def test_link_or_nonregular_file_is_listed_blocked_and_never_archived(self):
        root,states,_config=self.fixture()
        source=self.write(states,4)
        with patch.object(store,'_regular_file',return_value=False):
            rows=slots.list_slots(root)
            self.assertTrue(rows[4]['occupied'])
            self.assertTrue(rows[4]['blocked'])
            with self.assertRaises(slots.SlotArchiveError):slots.archive_slot(root,4)
        self.assertEqual(source.read_bytes(),b'preserve this save')
        self.assertFalse((root/'editor-slot-backups').exists())

    def test_nested_directory_redirection_is_blocked_before_reading_or_copying(self):
        root,states,_config=self.fixture()
        source=self.write(states,5,nested=True)
        regular=slots._directory
        with patch.object(slots,'_directory',side_effect=lambda p:False if p==source.parent else regular(p)):
            self.assertTrue(slots.list_slots(root)[5]['blocked'])
            with self.assertRaises(slots.SlotArchiveError):slots.archive_slot(root,5)
        self.assertTrue(source.exists())

    def test_size_limit_is_read_only_and_does_not_remove_the_slot(self):
        root,states,_config=self.fixture()
        source=self.write(states,6,b'12345')
        with patch.object(slots,'MAX_SLOT_FILE_BYTES',4):
            self.assertTrue(slots.list_slots(root)[6]['blocked'])
            with self.assertRaises(slots.SlotArchiveError):slots.archive_slot(root,6)
        self.assertEqual(source.read_bytes(),b'12345')

    def test_failed_copy_or_failed_readback_preserves_every_original(self):
        for mismatch in (False,True):
            with self.subTest(mismatch=mismatch):
                root,states,_config=self.fixture()
                paths=[self.write(states,1,b'first'),self.write(states,1,b'second',nested=True)]
                original=store._copy_exclusive
                def copy(source,destination):
                    if mismatch:
                        destination.write_bytes(b'bad copy')
                    else:
                        raise OSError('Injected copy error')
                with patch.object(store,'_copy_exclusive',side_effect=copy):
                    with self.assertRaises(slots.SlotArchiveError) as caught:slots.archive_slot(root,1)
                self.assertFalse(caught.exception.partial)
                self.assertTrue(caught.exception.archive_directory)
                self.assertEqual([p.read_bytes() for p in paths],[b'first',b'second'])

    def test_changed_source_after_copy_or_new_candidate_is_never_removed(self):
        for new_candidate in (False,True):
            with self.subTest(new_candidate=new_candidate):
                root,states,_config=self.fixture()
                source=self.write(states,1,b'original')
                original=store._copy_exclusive
                def copy(before,destination):
                    original(before,destination)
                    if new_candidate:self.write(states,1,b'new nested',nested=True)
                    else:source.write_bytes(b'replaced')
                with patch.object(store,'_copy_exclusive',side_effect=copy):
                    with self.assertRaises(slots.SlotArchiveError) as caught:slots.archive_slot(root,1)
                self.assertFalse(caught.exception.partial)
                self.assertTrue(source.exists())
                self.assertEqual(next(Path(caught.exception.archive_directory).glob('flat/*.p2s')).read_bytes(),b'original')

    def test_partial_unlink_failure_is_reported_and_all_backups_survive(self):
        root,states,_config=self.fixture()
        first=self.write(states,9,b'first')
        second=self.write(states,9,b'second',nested=True)
        original=Path.unlink
        def unlink(path,*args,**kwargs):
            if path==second:raise OSError('Injected unlink failure')
            return original(path,*args,**kwargs)
        with patch.object(Path,'unlink',unlink):
            with self.assertRaises(slots.SlotArchiveError) as caught:slots.archive_slot(root,9)
        self.assertTrue(caught.exception.partial)
        self.assertFalse(first.exists())
        self.assertEqual(second.read_bytes(),b'second')
        archive=Path(caught.exception.archive_directory)
        self.assertEqual(sorted(p.read_bytes() for p in archive.glob('*/*.p2s')),[b'first',b'second'])

    def test_backup_parent_redirection_is_rejected_and_source_untouched(self):
        root,states,_config=self.fixture()
        source=self.write(states,0)
        backup=root/'editor-slot-backups'
        backup.mkdir()
        regular=slots._directory
        with patch.object(slots,'_directory',side_effect=lambda p:False if p==backup else regular(p)):
            with self.assertRaises(slots.SlotArchiveError):slots.archive_slot(root,0)
        self.assertTrue(source.exists())

    def test_pause_guard_failure_after_copy_preserves_all_originals_and_copies(self):
        for failed_call in (3,4):
            with self.subTest(failed_call=failed_call):
                root,states,_config=self.fixture()
                source=self.write(states,2,b'paused save')
                calls=0
                def guard():
                    nonlocal calls
                    calls+=1
                    if calls==failed_call:raise ValueError('The emulator resumed')
                with self.assertRaises(slots.SlotArchiveError) as caught:
                    slots.archive_slot(root,2,guard=guard)
                self.assertFalse(caught.exception.partial)
                self.assertEqual(source.read_bytes(),b'paused save')
                self.assertEqual(next(Path(caught.exception.archive_directory).glob('flat/*.p2s')).read_bytes(),b'paused save')

    def test_pause_guard_failure_between_unlinks_reports_partial_and_preserves_remaining(self):
        root,states,_config=self.fixture()
        first=self.write(states,2,b'first')
        second=self.write(states,2,b'second',nested=True)
        calls=0
        def guard():
            nonlocal calls
            calls+=1
            if calls==5:raise ValueError('The emulator resumed')
        with self.assertRaises(slots.SlotArchiveError) as caught:
            slots.archive_slot(root,2,guard=guard)
        self.assertTrue(caught.exception.partial)
        self.assertFalse(first.exists())
        self.assertEqual(second.read_bytes(),b'second')
        archive=Path(caught.exception.archive_directory)
        self.assertEqual(sorted(path.read_bytes() for path in archive.glob('*/*.p2s')),[b'first',b'second'])

    def test_replacement_while_pause_guard_waits_is_rechecked_before_unlink(self):
        root,states,_config=self.fixture()
        source=self.write(states,3,b'old save')
        calls=0
        def guard():
            nonlocal calls
            calls+=1
            if calls==4:source.write_bytes(b'new save after guard')
        with self.assertRaises(slots.SlotArchiveError) as caught:
            slots.archive_slot(root,3,guard=guard)
        self.assertFalse(caught.exception.partial)
        self.assertEqual(source.read_bytes(),b'new save after guard')
        archive=Path(caught.exception.archive_directory)
        self.assertEqual(next(archive.glob('flat/*.p2s')).read_bytes(),b'old save')


if __name__=='__main__':unittest.main()
